function formatAmountInput(value:string):string{if(!value)return '';const trailingDecimal=value.endsWith('.');const [integerPart,...decimalParts]=value.split('.');const grouped=integerPart.replace(/\B(?=(\d{3})+(?!\d))/g,' ');const decimal=decimalParts.join('');return grouped+(decimalParts.length?(trailingDecimal&&decimal===''?',':','+decimal):trailingDecimal?',':'');}
function handleAmountInputChange(event:React.ChangeEvent<HTMLInputElement>,setValue:(value:string)=>void){const input=event.currentTarget;const raw=input.value;const caret=input.selectionStart??raw.length;const digitsBefore=raw.slice(0,caret).replace(/\D/g,'').length;const decimalBefore=/[,.]$/.test(raw.slice(0,caret));const parsed=parseAmountInput(raw);const formatted=formatAmountInput(parsed);setValue(parsed);let position=0;let digits=0;while(position<formatted.length&&digits<digitsBefore){if(/\d/.test(formatted[position]))digits++;position++;}if(decimalBefore){const separator=formatted.indexOf(',');if(separator>=0)position=separator+1;}requestAnimationFrame(()=>{if(document.activeElement===input)input.setSelectionRange(position,position);});}
