 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('flowmoney_theme',dark?'dark':'light');},[dark]);useEffect(()=>{window.scrollTo(0,0);},[section]);useEffect(()=>{localStorage.setItem('flowmoney_lang',lang);document.documentElement.lang=lang;},[lang]);useEffect(()=>{localStorage.setItem('flowmoney_country',countryCode);setCurrency(selectedCountry.currency);localStorage.setItem('flowmoney_expense_currency',selectedCountry.currency);},[countryCode]);useEffect(()=>{localStorage.setItem('flowmoney_expense_currency',currency);},[currency]);useEffect(()=>{localStorage.setItem('flowmoney_exchange_rub',rub);localStorage.setItem('flowmoney_exchange_usdt',usdt);localStorage.setItem('flowmoney_exchange_rate',rate);localStorage.setItem('flowmoney_exchange_fee',fee);},[rub,usdt,rate,fee]);
