 useEffect(()=>{let active=true;async function restoreSession(){try{if(getToken()){const restoredUser=await api<User>('/auth/me');if(active)setUser(restoredUser);}}catch{setToken(null);}finally{if(active)setSessionLoading(false);}}void restoreSession();return()=>{active=false;};},[]);useEffect(()=>{if(user)void refresh();},[user]);useEffect(()=>{if(!user)return;let active=true;api<{name:string|null;country:string|null}>('/auth/profile').then(profile=>{if(active){setProfileName(profile.name||'');setProfileCountry(profile.country||'');}}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Could not load profile');});return()=>{active=false;};},[user]);
 async function auth(e:React.FormEvent){e.preventDefault();setError('');setNotice('');const nextErrors:{email?:string;password?:string}={};const normalizedEmail=email.trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizedEmail))nextErrors.email='Please enter a valid email address.';if(password.length<8)nextErrors.password='Password must be at least 8 characters.';setAuthFieldErrors(nextErrors);if(Object.keys(nextErrors).length)return;setLoading(true);try{if(authMode==='register'){const result=await api<{message:string}>('/auth/register',{method:'POST',body:JSON.stringify({email:normalizedEmail,password})});setNotice(result.message);setAuthMode('login');setPassword('');return;}const r=await api<{token:string;user:User}>('/auth/login',{method:'POST',body:JSON.stringify({email:normalizedEmail,password})});setToken(r.token);setDashboardInitialized(false);setUser(r.user);}catch(e){setError(e instanceof Error?e.message:'Authentication failed');}finally{setLoading(false);}}
