 const chartData=useMemo(()=>{const now=new Date();const locale=lang==='ru'?'ru-RU':'en-US';if(chartRange==='year'){const buckets=Array.from({length:12},(_,i)=>{const start=new Date(now.getFullYear(),now.getMonth()-11+i,1);const end=new Date(now.getFullYear(),now.getMonth()-10+i,1);return{label:start.toLocaleDateString(locale,{month:'short'}),start,end,value:0};});for(const expense of summary.expenses){const date=new Date(expense.date);const bucket=buckets.find(x=>date>=x.start&&date<x.end);if(bucket)bucket.value+=expense.amountVnd??0;}return buckets.map(({label,value})=>({label,value}));}const hours=chartRange==='day'?24:chartRange==='week'?24*7:24*30;const count=chartRange==='day'?8:chartRange==='week'?7:5;const start=new Date(now.getTime()-hours*60*60*1000);const width=(now.getTime()-start.getTime())/count;const buckets=Array.from({length:count},(_,i)=>{const from=new Date(start.getTime()+i*width);const to=new Date(start.getTime()+(i+1)*width);return{label:chartRange==='day'?from.toLocaleTimeString(locale,{hour:'2-digit',hour12:false}):chartRange==='week'?from.toLocaleDateString(locale,{weekday:'short'}):from.toLocaleDateString(locale,{day:'numeric',month:'short'}),start:from,end:to,value:0};});for(const expense of summary.expenses){const date=new Date(expense.date);const bucket=buckets.find(x=>date>=x.start&&date<x.end);if(bucket)bucket.value+=expense.amountVnd;}return buckets.map(({label,value})=>({label,value}));},[summary.expenses,chartRange,lang]);const chartMax=Math.max(1,...chartData.map(x=>x.value));const chartTotal=chartData.reduce((sum,x)=>sum+x.value,0);const balanceVndPerRub=currentVndPerRub??(planningVndPerUsdt&&rubPerUsdt?planningVndPerUsdt/rubPerUsdt:null);const balanceVndPerUsdt=currentVndPerUsdt??planningVndPerUsdt;const balanceEquivalents=calculateBalanceEquivalents(summary.balanceVnd,balanceVndPerUsdt,balanceVndPerRub);
 async function saveExchange(){const rubValue=Number(rub);const usdtValue=Number(usdt);const receivedValue=vndReceivedInput.trim()?Number(vndReceivedInput):undefined;if(!Number.isFinite(rubValue)||rubValue<=0){setError('Enter a positive RUB amount.');return;}if(exchangeMode==='RUB_TARGET'){if(receivedValue===undefined||!Number.isFinite(receivedValue)||receivedValue<=0){setError('Enter the actual amount received in the target currency.');return;}const targetRate=selectedCountry.currency==='VND'?1:Number(targetToVndRateInput);if(!Number.isFinite(targetRate)||targetRate<=0){setError('Enter the VND equivalent for one unit of the target currency.');return;}try{await api('/exchanges',{method:'POST',body:JSON.stringify({mode:'RUB_TARGET',rubSpent:rubValue,targetCurrency:selectedCountry.currency,targetReceived:receivedValue,targetToVndRate:targetRate})});setVndReceivedInput('');setNotice(t(lang,'Direct target-currency exchange saved. The VND equivalent updates your shared budget.'));setSection('overview');await refresh();}catch(e){setError(e instanceof Error?e.message:'Could not save exchange');}return;}if(receivedValue!==undefined&&(!Number.isFinite(receivedValue)||receivedValue<=0)){setError('Enter a positive VND amount.');return;}if(!Number.isFinite(usdtValue)||usdtValue<=0){setError('Check the RUB and USDT amounts.');return;}try{const payload:Record<string,number|string>={mode:'RUB_USDT_VND',rubSpent:rubValue,usdtReceived:usdtValue};if(receivedValue===undefined&&planningVndPerUsdt>0)payload.planningVndPerUsdt=planningVndPerUsdt;if(receivedValue!==undefined)payload.vndReceived=receivedValue;await api('/exchanges',{method:'POST',body:JSON.stringify(payload)});setVndReceivedInput('');setNotice(t(lang,'Exchange saved. Your planning balance and future estimates have been updated.'));setSection('overview');await refresh();}catch(e){setError(e instanceof Error?e.message:'Could not save exchange');}}
 async function saveExpense(e:React.FormEvent){e.preventDefault();const n=Number(amount);if(!title.trim()||!Number.isFinite(n)||n<=0){setError('Enter an expense name and a positive amount.');return;}let amountVnd:number|null=null;let targetToVndRate:number|undefined;if(currency==='VND')amountVnd=n;else if(currency==='USDT')amountVnd=currentVndPerUsdt!=null&&currentVndPerUsdt>0?n*currentVndPerUsdt:null;else if(currency==='RUB')amountVnd=currentVndPerRub!=null&&currentVndPerRub>0?n*currentVndPerRub:null;else{const localRate=localToVndRate.trim()?Number(localToVndRate):null;if(localRate!=null&&(!Number.isFinite(localRate)||localRate<=0)){setError('Currency conversion rate must be positive.');return;}if(localRate!=null){targetToVndRate=localRate;amountVnd=n*localRate;}}const charged=usdtCharged.trim()?Number(usdtCharged):undefined;if(charged!==undefined&&(!Number.isFinite(charged)||charged<=0)){setError('USDT card debit must be a positive number.');return;}try{await api('/expenses',{method:'POST',body:JSON.stringify({title,category,amount:n,currency,...(amountVnd!=null?{amountVnd}:{}),...(targetToVndRate!=null?{targetToVndRate}:{}),...(currency==='VND'&&charged?{usdtCharged:charged}:{}),date:new Date().toISOString()})});setTitle('');setAmount('');setUsdtCharged('');setLocalToVndRate('');setNotice('Expense added.');await refresh();}catch(e){setError(e instanceof Error?e.message:'Could not save expense');}}
